"""Inspect LED-safe visual reduction and projectile-width collision closure."""
import html,json,sys
from pathlib import Path


def main():
    out=Path(sys.argv[1]).resolve();r=json.loads((out/'summary.json').read_bytes());v=json.loads((out/'validation.json').read_bytes());scopes={'whole':('Whole Base','e15-a60'),'rear':('Reverse view','e15-a180'),'top':('Top view','top')}
    for source,label in [(4268930,'Crossbar'),(4527988,'Lower housing'),(4392221,'Tall cover A'),(4314593,'Tall cover B'),(4353403,'Tall cover C'),(4756187,'Backing shell'),(4099408,'Armor module'),(4561335,'Small module'),(4072376,'Green optic'),(4599538,'Small LED assembly')]:scopes[str(source)]=(label,'unit-'+str(source))
    for source,label in [(4392221,'Cover light strip'),(4099408,'Armor-module LED'),(4561335,'Small-module LED'),(4072376,'Green optic'),(4599538,'Small LED assembly')]:scopes['light-'+str(source)]=(label+' · lights only','light-unit-'+str(source))
    scopes['lights-whole']=('All LED geometry · isolated','led-e15-a60');scopes['lights-rear']=('All LED geometry · reverse','led-e15-a180');panels=[]
    for key,(label,suffix) in scopes.items():
        if suffix.startswith('light-unit-'):
            paths=[out/f'{suffix}-{s}.png' for s in ('before','visual')];kinds=('before','visual')
        elif suffix.startswith('led-'):
            suffix=suffix[4:];paths=[out/f'led-{s}-{suffix}.png' for s in ('before','visual')];kinds=('before','visual')
        elif suffix.startswith('unit-'):
            kinds=('before','visual','collision-before','collision');paths=[out/f'{suffix}-{s}.png' for s in kinds]
        else:
            kinds=('before','visual','collision-before','collision');paths=[out/f'{s}-{suffix}.png' for s in kinds]
        figures=''.join(f'<figure data-kind="{kind}"><figcaption>{"Approved" if kind in ("before","collision-before") else "Candidate"} {"collision" if kind.startswith("collision") else "visual"}</figcaption><img src="{html.escape(str(path))}" alt="{html.escape(label+": "+kind)}"></figure>' for kind,path in zip(kinds,paths) if path.exists());panels.append(f'<section class="comparison" data-scope="{key}" '+('' if key=='whole' else 'hidden')+'><div class="pair">'+figures+'</div></section>')
    options=''.join(f'<option value="{k}">{html.escape(label)}</option>' for k,(label,_) in scopes.items());rows=''.join(f'<tr><td>{label}</td><td>{before:,}</td><td>{after:,}</td><td>{(1-after/before)*100:.1f}%</td></tr>' for label,before,after in [('Visual triangles',275172,r['stages']['visual']['definition_triangles']),('Collision triangles',20095,r['stages']['collision']['definition_triangles']),('LED triangles',16806,r['stages']['visual']['led_triangles'])])
    page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{margin:0;font:14px/1.5 var(--font-sans,system-ui);color:var(--foreground,#17202f)}h3{font-size:17px;margin:15px 0 8px}p{margin:8px 0}.stats{display:flex;gap:24px;flex-wrap:wrap}.stats b{display:block;font-size:24px}.note{font-size:12px;color:var(--muted-foreground,#667085)}nav{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}select,button{font:inherit;padding:7px;border:1px solid var(--border,#aaa);border-radius:6px;background:var(--background,white);color:inherit;cursor:pointer;max-width:100%}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}figure{margin:0}figcaption{font-size:12px;margin:5px 0}img{width:100%;display:block;border-radius:var(--radius,6px)}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}td,th{padding:6px 0;border-bottom:1px solid var(--border,#ddd);text-align:right}td:first-child,th:first-child{text-align:left}body[data-mode=visual] figure[data-kind^=collision],body[data-mode=collision] figure:not([data-kind^=collision]){display:none}body[data-mode=single] figure:not([data-kind=visual]){display:none}body[data-mode=single] .pair{grid-template-columns:1fr}[hidden]{display:none!important}@media(max-width:430px){.pair{grid-template-columns:1fr}table{font-size:12px}}
</style></head><body data-mode="visual"><div class="stats"><div><b>142,120</b>visual triangles / Base</div><div><b>16,857</b>collision triangles / Base</div><div><b>52.6%</b>fewer LED triangles</div></div><p class="note">Review candidates against the previously approved 275,172 visual / 20,095 collision model. Original CAD and runtime assets are unchanged. Two placed Bases share one definition.</p><nav><select id="scope" aria-label="Part and view" onchange="update()">'''+options+'''</select><button id="visual" onclick="document.body.dataset.mode='visual'">Compare visuals</button><button id="collision" onclick="document.body.dataset.mode='collision'">Compare collision</button><button onclick="document.body.dataset.mode='single'">Candidate only</button></nav>'''+''.join(panels)+'''<p class="note">Use the light-only close-ups to inspect strip ends, rounded corners and source colors. Collision comparisons use cyan for readability.</p><table><tr><th>Per Base</th><th>Approved</th><th>Candidate</th><th>Saving</th></tr>'''+rows+f'''</table><p>The new visual is <b>80.0% smaller than the original 709,354-triangle native mesh</b>. Regular material regions use a 0.25 mm simplifier metric with a separate 1 mm sampled-distance guard. LED regions use 0.025 mm and 0.1 mm respectively. Material borders stay locked; source colors remain unchanged.</p><h3>LED appearance checks</h3><p>LED geometry drops from 16,806 to 7,960 triangles. The largest measured LED sample distance is 0.0955 mm. Across 18 isolated-light views, at most {v['maximum_led_mask_fraction']*1440000:.0f} of 1,440,000 pixels change foreground membership. The worst enlarged LED silhouette change is {v['maximum_led_closeup_mask_relative_fraction']*100:.3f}% of its source foreground area.</p><p class="note">Whole-Base comparisons: at most {v['maximum_whole_rgb_fraction']*100:.3f}% changed RGB pixels above 10/255, and {v['maximum_whole_mask_fraction']*100:.4f}% foreground change. These are sampled source-pose diagnostic renders, not continuous error or moving-pose guarantees.</p><h3>Close gaps strictly narrower than 17 mm</h3><p>A rigid 17 mm ball cannot pass through a narrower opening. Filling the opening can change partial entry, grazing contact and bounce, so the width rule is kept separate from mesh approximation error. Openings exactly 17 mm wide are retained.</p><p>This candidate closes <b>335 complete circular bores</b> across the crossbar, covers and module frame, and processes <b>74 inner loops</b> in four backing-panel profiles, including holes already capped by the preceding area policy. Width is measured on native curves, including edge-aligned calipers for rotated slots; a long 15 mm slot can close even if its area is large.</p><p class="note">The lower housing's rebuilt trial did not improve its approved collision count and was retained. The closure pass handles complete bores and explicitly selected planar profiles. It does not yet close every arbitrary inter-part seam or fuse independently moving members. Larger openings, broad returns and gameplay detector authority remain separate.</p><p class="note">295 tests run: 294 passed, one optional skip. Fixtures cover a rotated narrow slot, the exact 17 mm boundary, and a 17 mm sphere fitting an 18 mm bore but intersecting a 16 mm bore. No runtime bounce equivalence is claimed.</p><script>function update(){{const key=document.getElementById('scope').value;document.querySelectorAll('.comparison').forEach(p=>p.hidden=p.dataset.scope!==key);const light=key.startsWith('light');document.getElementById('collision').disabled=light;if(light)document.body.dataset.mode='visual';}}update();console.assert(document.querySelectorAll('.comparison').length===20);console.log('20 scopes, LED close-ups and separate collision comparisons ready.');</script></body></html>'''
    (out/'review.html').write_text(page);print(out/'review.html')


if __name__=='__main__':main()
